import React from 'react';
import PropTypes from 'prop-types';
import StatusBadge from './status';

export default function OrderCard({ order, isRecues = false }) {
  return (
    <div className="order-card">
      <div className="order-header">
        <div className="order-info">
          <h3 className="order-name">{order.name}</h3>
          <StatusBadge status={order.status} />
        </div>
      </div>

      <div className="order-body">
        <p>
          <strong>Produit:</strong> {order.product}
        </p>
        <p>
          <strong>Taille:</strong> {order.size}
        </p>
        <p>
          <strong>Téléphone:</strong> {order.phone}
        </p>
        <p>
          <strong>Adresse:</strong> {order.address}
        </p>
        <p>
          <strong>Wilaya:</strong> {order.wilaya}
        </p>
        <p>
          <strong>Date:</strong> {order.date}
        </p>
        {order.notes && (
          <p>
            <strong>Notes:</strong> {order.notes}
          </p>
        )}
      </div>

      {!isRecues && (
        <div className="order-actions">
          <button className="btn-accept">Accepter</button>
          <button className="btn-reject">Refuser</button>
        </div>
      )}
    </div>
  );
}

OrderCard.propTypes = {
  order: PropTypes.shape({
    id: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
    name: PropTypes.string.isRequired,
    status: PropTypes.string.isRequired,
    product: PropTypes.string.isRequired,
    size: PropTypes.string.isRequired,
    phone: PropTypes.string.isRequired,
    address: PropTypes.string.isRequired,
    wilaya: PropTypes.string.isRequired,
    date: PropTypes.string.isRequired,
    notes: PropTypes.string,
  }).isRequired,
  isRecues: PropTypes.bool,
};
